mapper.select:
SELECT event_date
FROM school_calendar_event
WHERE school_id = #{schoolId}
  AND term_id = #{termId}
  AND day_type IN ('HOLIDAY', 'SUSPENDED')
  AND event_date BETWEEN #{startDate} AND #{endDate}
ORDER BY event_date

mapper.insert:
INSERT INTO lesson_session (
    school_id, offering_id, session_date, start_time, end_time, classroom
) VALUES (
    #{schoolId}, #{offeringId}, #{sessionDate}, #{startTime}, #{endTime}, #{classroom}
)
ON DUPLICATE KEY UPDATE id = id

mapper.select:
SELECT offering_id
FROM lesson_session
WHERE id = #{sessionId}

SELECT COUNT(*)
FROM attendance
WHERE session_id = #{sessionId}

mapper.update:
UPDATE lesson_session
SET status = #{status}
    , notes = #{notes}
WHERE id = #{sessionId}

mapper.select:
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM lesson_session ls
    JOIN enrollment e
      ON e.offering_id = ls.offering_id
     AND e.student_id = #{studentId}
    WHERE ls.id = #{sessionId}
      AND ls.offering_id = #{offeringId}
      AND (
          (
              e.enrolled_at <= TIMESTAMP(ls.session_date, ls.start_time)
              AND (
                  e.canceled_at IS NULL
                  OR e.canceled_at >= TIMESTAMP(ls.session_date, ls.start_time)
              )
          )
          OR EXISTS (
              SELECT 1
              FROM attendance historic
              WHERE historic.session_id = ls.id
                AND historic.student_id = e.student_id
          )
      )
) THEN 1 ELSE 0 END
